import type { Metadata } from "next";
import { site } from "./content";

/**
 * Builds the <title>, description, Open Graph and Twitter tags for a page.
 * The Open Graph image is generated by src/app/opengraph-image.tsx.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title?: string;
  description: string;
  path: string;
}): Metadata {
  const fullTitle = title ? `${title} | ${site.name}` : `${site.name}: ${site.fullName}`;
  // A page's openGraph block replaces the layout's, so the shared image is added on every page.
  const image = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name}: ${site.fullName}` };
  return {
    title: title ?? { absolute: fullTitle },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_CA",
      url: path,
      title: fullTitle,
      description,
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [image],
    },
  };
}
